expr = input("Enter an expression: ")
stack = []
pairs = {')': '(', ']': '[', '}': '{'}
for ch in expr:
    if ch in "([{":
        stack.append(ch)
    elif ch in ")]}":
        if not stack or stack[-1] != pairs[ch]:
            print("Parentheses are NOT balanced")
            return
        stack.pop()
if not stack:
    print("Parentheses are balanced!")
else:
